package com.problems.strings;

public class RepeatedSubstringPattern {

    static void main() {
        System.out.println(repeatedSubstringPattern("ab"));
        System.out.println(repeatedSubstringPattern("abcabcb"));
        System.out.println(repeatedSubstringPattern("abcabc"));
        System.out.println(repeatedSubstringPattern("ababab"));
        System.out.println(repeatedSubstringPattern("abaababaab"));
        System.out.println(repeatedSubstringPattern("babbabbabbabbab"));
        System.out.println(repeatedSubstringPattern(""));
        System.out.println(repeatedSubstringPattern(""));
    }

    public static boolean repeatedSubstringPattern(final String s) {
        if (s.isEmpty() || s.length() == 1) {
            return false;
        }

        for (int i = 0; i < s.length() / 2; i++) {

            if (s.substring(0, i + 1).repeat(s.length() / (i + 1)).equals(s)) {
                return true;
            }
        }

        return false;

    }

}
